    --SmartThemeCheckboxTickColor: var(--mz-day-paper);
    --reasoning-body-color: var(--SmartThemeEmColor);
    --reasoning-em-color: color-mix(in srgb, var(--SmartThemeEmColor) 67%, var(--SmartThemeBlurTintColor) 33%);
    color-scheme: light;
}

