:root:not(.dn-night)[data-paper="deep-white"] { --mz-day-paper: #F5F1E5; --mz-day-board: #EEE9DB; }

:root:not(.dn-night)[data-paper="cosmic-latte"] { --mz-day-paper: #FFF8E7; --mz-day-board: #F8F0DD; }

:root:not(.dn-night) {
    
    --mz-meta: color-mix(in srgb, var(--SmartThemeBodyColor) 80%, var(--SmartThemeChatTintColor));
    --mz-surface: color-mix(in srgb, var(--SmartThemeBodyColor) 5%, transparent);

    
    --mz-read-weight: var(--mz-day-read-weight);

    
    --mz-grain: none;

    
    --mz-desk: color-mix(in srgb, var(--SmartThemeBodyColor) var(--mz-day-desk), var(--SmartThemeBlurTintColor));

    
    --mz-plate-filter: var(--mz-day-plate-filter);
    --mz-plate-blend: multiply;

    
    --white20a: color-mix(in srgb, var(--SmartThemeBodyColor) 30%, transparent);
    --white30a: color-mix(in srgb, var(--SmartThemeBodyColor) 60%, transparent);
    --white50a: color-mix(in srgb, var(--SmartThemeBodyColor) 80%, transparent);
    --white60a: color-mix(in srgb, var(--SmartThemeBodyColor) 85%, transparent);
    --white70a: color-mix(in srgb, var(--SmartThemeBodyColor) 90%, transparent);
    --black30a: color-mix(in srgb, var(--SmartThemeBodyColor) 5%, transparent);
    --black50a: color-mix(in srgb, var(--SmartThemeBodyColor) 8%, transparent);
    --black60a: color-mix(in srgb, var(--SmartThemeBodyColor) 10%, transparent);
    --black70a: color-mix(in srgb, var(--SmartThemeBodyColor) 12%, transparent);
    --grey30a: color-mix(in srgb, var(--SmartThemeBodyColor) 8%, transparent);
    --interactable-outline-color: var(--SmartThemeBodyColor);
    --interactable-outline-color-faint: color-mix(in srgb, var(--SmartThemeBodyColor) 30%, transparent);
}

:root:not(.dn-night) ::selection {
    background-color: color-mix(in srgb, var(--mz-accent) 22%, transparent);
}

:root:not(.dn-night) .drawer-icon {
    font-size: calc(var(--mainFontSize) * 1.35);
}

:root:not(.dn-night) .drawer-icon.closedIcon {
    opacity: 1;
    color: var(--mz-ink);
}

:root:not(.dn-night) .drawer-icon.closedIcon:hover {
    color: var(--mz-accent);
}

:root:not(.dn-night) .drawer-icon.openIcon {
    color: var(--mz-accent);
    box-shadow: 0 5px 0 -2px var(--mz-accent);
}

@media screen and (max-width: 1000px) {
:root:not(.dn-night) .drawer-icon {
        font-size: calc(var(--mainFontSize) * 1.5);
    }

}
/* ==== end themes/mozhi/day.css ==== */
}
